      history:['역사에서 문추는 관도 싸움 앞머리 연진에서 조조의 미끼에 걸려 죽었다.','이 길에서 그는 살아남았고, 원씨의 마지막 기병을 이끈다.','조조와 맺은 맹약은 원상의 목을 요구하지만, 문추는 그 목을 내줄 생각이 없다.'],
